import{_ as t}from"./chunks/qgc_mc_pid_tuning_rate_controller.CKJFCyuw.js";import{_ as o}from"./chunks/qgc_mc_pid_tuning_simple_control.C98VxfZ9.js";import{_ as i,o as s,c as a,al as l}from"./chunks/framework.7vp1BMOE.js";const _=JSON.parse('{"title":"Інструкція з налаштування мультикоптера PID (Manual/Basic)","description":"","frontmatter":{},"headers":[],"relativePath":"uk/config_mc/pid_tuning_guide_multicopter_basic.md","filePath":"uk/config_mc/pid_tuning_guide_multicopter_basic.md"}'),r={name:"uk/config_mc/pid_tuning_guide_multicopter_basic.md"};function n(c,e,p,u,h,m){return s(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="інструкція-з-налаштування-мультикоптера-pid-manual-basic" tabindex="-1">Інструкція з налаштування мультикоптера PID (Manual/Basic) <a class="header-anchor" href="#інструкція-з-налаштування-мультикоптера-pid-manual-basic" aria-label="Permalink to &quot;Інструкція з налаштування мультикоптера PID (Manual/Basic)&quot;">​</a></h1><p>This tutorial explains how to <em>manually</em> tune the PID loops on PX4 for all <a href="./../airframes/airframe_reference#copter">multicopter setups</a> (Quads, Hexa, Octo etc).</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><a href="./../config/autotune_mc">Autotune</a> is recommended for most users, as it is far faster, easier and provides good tuning for most frames. Рекомендується ручна настройка для кадрів, де автоналаштування не працює, або де важлива дотюнінг.</p></div><p>Generally if you&#39;re using an appropriate <a href="./../airframes/airframe_reference#copter">supported frame configuration</a>, the default tuning should allow you to fly the vehicle safely. Tuning is recommended for all new vehicle setups to get the <em>very best</em> performance, because relatively small hardware and assembly changes can affect the gains required tuning gains for optimal flight. Наприклад, різні ESC або двигуни змінюють оптимальні налаштування коефіцієнтів настройки.</p><h2 id="введення" tabindex="-1">Введення <a class="header-anchor" href="#введення" aria-label="Permalink to &quot;Введення&quot;">​</a></h2><p>PX4 uses <strong>P</strong>roportional, <strong>I</strong>integral, <strong>D</strong>erivative (PID) controllers (these are the most widespread control technique).</p><p>The <em>QGroundControl</em> <strong>PID Tuning</strong> setup provides real-time plots of the vehicle setpoint and response curves. The goal of tuning is to set the P/I/D values such that the <em>Response</em> curve matches the <em>Setpoint</em> curve as closely as possible (i.e. a fast response without overshoots).</p><p><img src="'+t+'" alt="QGC Rate Controller Tuning UI"></p><p>Контролери рівні, що означає, що контролер більш високого рівня передає свої результати контролеру нижчого рівня. The lowest-level controller is the <strong>rate controller</strong>, followed by the <strong>attitude controller</strong>, and finally the <strong>velocity &amp; position controller</strong>. Налаштування PID потрібно виконати в тому ж порядку, починаючи з регулятора швидкості, оскільки воно вплине на всі інші регулятори.</p><p>The testing procedure for each controller (rate, attitude, velocity/position) and axis (yaw, roll, pitch) is always the same: create a fast setpoint change by moving the sticks very rapidly and observe the response. Потім налаштуйте слайдери (як обговорено нижче), щоб покращити відстеження реакції на задане значення.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li>Налаштування регулятора швидкості є найважливішим, і якщо воно налаштовано добре, інші регулятори часто не потребують жодних або лише незначних корекцій</li><li>Зазвичай для кочення і тангажу можна використовувати ті ж самі коефіцієнти налаштування.</li><li>використовуйте режим Acro/Stabilized/Altitude для налаштування контролера швидкості</li><li>Use <a href="./../flight_modes_mc/position">Position mode</a> to tune the <em>Velocity Controller</em> and the <em>Position Controller</em>. Make sure to switch to the <em>Simple position control</em> mode so you can generate step inputs. <img src="'+o+'" alt="QGC PID tuning: Simple control selector"></li></ul></div><h2 id="передумови" tabindex="-1">Передумови <a class="header-anchor" href="#передумови" aria-label="Permalink to &quot;Передумови&quot;">​</a></h2><ul><li><p>You have selected the closest matching <a href="./../config/airframe">default frame configuration</a> for your vehicle. This should give you a vehicle that already flies.</p></li><li><p>You should have done an <a href="./../advanced_config/esc_calibration">ESC calibration</a>.</p></li><li><p>If using PWM outputs their minimum values should be set correctly in the <a href="./../config/actuators">Actuator Configuration</a>. These need to be set low, but such that the <strong>motors never stop</strong> when the vehicle is armed.</p><p>This can be tested in <a href="./../flight_modes_mc/acro">Acro mode</a> or in <a href="./../flight_modes_mc/manual_stabilized">Stabilized mode</a>:</p><ul><li>Remove propellers</li><li>Arm the vehicle and lower the throttle to the minimum</li><li>Tilt the vehicle to all directions, about 60 degrees</li><li>Check that no motors turn off</li></ul></li><li><p>Use a high-rate telemetry link such as WiFi if at all possible (a typical low-range telemetry radio is not fast enough for real-time feedback and plots). This is particularly important for the rate controller.</p></li><li><p>Disable <a href="./../advanced_config/parameter_reference#MC_AIRMODE">MC_AIRMODE</a> before tuning a vehicle (there is an options for this in the PID tuning screen).</p></li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Poorly tuned vehicles are likely to be unstable, and easy to crash. Make sure to have assigned a <a href="./../config/safety#emergency-switches">Kill switch</a>.</p></div><h2 id="tuning-procedure" tabindex="-1">Tuning Procedure <a class="header-anchor" href="#tuning-procedure" aria-label="Permalink to &quot;Tuning Procedure&quot;">​</a></h2><p>The tuning procedure is:</p><ol><li><p>Arm the vehicle, takeoff, and hover (typically in <a href="./../flight_modes_mc/position">Position mode</a>).</p></li><li><p>Open <em>QGroundControl</em> <strong>Vehicle Setup &gt; PID Tuning</strong><img src="'+t+`" alt="QGC Rate Controller Tuning UI"></p></li><li><p>Select the <strong>Rate Controller</strong> tab.</p></li><li><p>Confirm that the airmode selector is set to <strong>Disabled</strong></p></li><li><p>Set the <em>Thrust curve</em> value to: 0.3 (PWM, power-based controllers) or 1 (RPM-based ESCs)</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>For PWM, power-based and (some) UAVCAN speed controllers, the control signal to thrust relationship may not be linear. As a result, the optimal tuning at hover thrust may not be ideal when the vehicle is operating at higher thrust.</p><p>The thrust curve value can be used to compensate for this non-linearity:</p><ul><li>For PWM controllers, 0.3 is a good default (which may benefit from <a href="./../config_mc/pid_tuning_guide_multicopter#thrust-curve">further tuning</a>).</li><li>For RPM-based controllers, use 1 (no further tuning is required as these have a quadratic thrust curve).</li></ul><p>For more information see the <a href="./../config_mc/pid_tuning_guide_multicopter#thrust-curve">detailed PID tuning guide</a>.</p></div></li></ol><p>:::</p><ol start="6"><li><p>Set the <em>Select Tuning</em> radio button to: <strong>Roll</strong>.</p></li><li><p>(Optionally) Select the <strong>Automatic Flight Mode Switching</strong> checkbox. This will <em>automatically</em> switch from <a href="./../flight_modes_mc/position">Position mode</a> to <a href="./../flight_modes_mc/manual_stabilized">Stabilised mode</a> when you press the <strong>Start</strong> button</p></li><li><p>For rate controller tuning switch to <em>Acro mode</em>, <em>Stabilized mode</em> or <em>Altitude mode</em> (unless automatic switching is enabled).</p></li><li><p>Select the <strong>Start</strong> button in order to start tracking the setpoint and response curves.</p></li><li><p>Rapidly move the <em>roll stick</em> full range and observe the step response on the plots.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Stop tracking to enable easier inspection of the plots. This happens automatically when you zoom/pan. Use the <strong>Start</strong> button to restart the plots, and <strong>Clear</strong> to reset them.</p></div></li></ol><p>:::</p><ol start="11"><li><p>Modify the three PID values using the sliders (for roll rate-tuning these affect <code>MC_ROLLRATE_K</code>, <code>MC_ROLLRATE_I</code>, <code>MC_ROLLRATE_D</code>) and observe the step response again. The values are saved to the vehicle as soon as the sliders are moved.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The goal is for the <em>Response</em> curve to match the <em>Setpoint</em> curve as closely as possible (i.e. a fast response without overshoots).</p></div></li></ol><p>:::</p><pre><code>The PID values can be adjusted as follows:

- P (пропорційне) або К підсилення:
  - збільште це для більшої реакції
  - зменшити, якщо відповідь перевищує і / або коливається (до певної міри збільшення значення D також допомагає).
- D (похідне) надходження:
  - це можна збільшити, щоб заглушити перевищення та коливання
  - збільшуйте це лише настільки, наскільки це потрібно, оскільки це підсилює шум (і може призвести до нагрітих моторів)
- I (інтегральний) коефіцієнт отримання:
  - використовується для зменшення поміченої похибки стану рівноваги
  - якщо значення занадто низьке, відповідь може ніколи не досягти заданої точки (наприклад, у вітрових умовах)
  - якщо занадто високий, можуть виникнути повільні коливання
</code></pre><ol start="12"><li>Повторіть процес налаштування вище для крена та курсу: <ul><li>Use <em>Select Tuning</em> radio button to select the axis to tune</li><li>Перемістіть відповідні палички (тобто паличку крена для крена, паличку риштування для риштування).</li><li>Для налаштування крену почніть з тих самих значень, що й для крену.<div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Use the <strong>Save to Clipboard</strong> and <strong>Reset from Clipboard</strong> buttons to copy the roll settings for initial pitch settings.</p></div></li></ul></li></ol><p>:::</p><ol start="13"><li><p>Повторіть процес налаштування контролера нахилу для всіх осей.</p></li><li><p>Повторіть процес налаштування контролерів швидкості та позицій (на всіх осях).</p><ul><li><p>Використовуйте режим позиції при налаштуванні цих контролерів</p></li><li><p>Select the <strong>Simple position control</strong> option in the <em>Position control mode ...</em> selector (this allows direct control for the generation of step inputs)</p><p><img src="`+o+'" alt="QGC PID tuning: Simple control selector"></p></li></ul></li></ol><p>Готово! Пам&#39;ятайте увімкнути повітряний режим перед виходом з налаштувань.</p>',27)])])}const b=i(r,[["render",n]]);export{_ as __pageData,b as default};
